import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"又跟老师汇报了！画了图形摘要和技术路线图，还想开北极渔业","description":"今天又跟老师汇报了一下论文，绘制了论文的图形摘要和技术路线图；另外有了新想法——想开辟北极渔业的研究方向，准备最近研究一下。","frontmatter":{"title":"又跟老师汇报了！画了图形摘要和技术路线图，还想开北极渔业","date":"2026-09-09T00:00:00.000Z","tags":["日记"],"description":"今天又跟老师汇报了一下论文，绘制了论文的图形摘要和技术路线图；另外有了新想法——想开辟北极渔业的研究方向，准备最近研究一下。"},"headers":[],"relativePath":"posts/diary-20260909.md","filePath":"posts/diary-20260909.md","lastUpdated":null}'),s={name:"posts/diary-20260909.md"};function p(n,a,i,d,l,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="又跟老师汇报了-画了图形摘要和技术路线图-还想开北极渔业" tabindex="-1">又跟老师汇报了！画了图形摘要和技术路线图，还想开北极渔业 <a class="header-anchor" href="#又跟老师汇报了-画了图形摘要和技术路线图-还想开北极渔业" aria-label="Permalink to &quot;又跟老师汇报了！画了图形摘要和技术路线图，还想开北极渔业&quot;">​</a></h1><p>今天又是汇报日，但比上次从容多了，另外还冒出了个挺让人兴奋的新念头 😏。</p><h2 id="又跟老师汇报了论文" tabindex="-1">又跟老师汇报了论文 <a class="header-anchor" href="#又跟老师汇报了论文" aria-label="Permalink to &quot;又跟老师汇报了论文&quot;">​</a></h2><p><strong>今天又跟老师汇报了一下论文</strong> 📊。</p><p>这轮汇报比之前顺——稿子改过了、图也重做了，讲的时候心里有底，不像上次汇报算法时那样&quot;嘴上在讲、心里打鼓&quot;。把这一轮的修改情况、目前的状态跟老师过了一遍，该听的意见也听了。</p><p>汇报这事儿就是这样，你准备得越足，讲得越稳；讲得越稳，老师越能给你有价值的反馈。前几次的紧张，现在回头看都变成了经验值嘿嘿。</p><h2 id="图形摘要-技术路线图-画好了" tabindex="-1">图形摘要 + 技术路线图：画好了 <a class="header-anchor" href="#图形摘要-技术路线图-画好了" aria-label="Permalink to &quot;图形摘要 + 技术路线图：画好了&quot;">​</a></h2><p>今天还干了两件&quot;门面工程&quot;——<strong>绘制了论文的图形摘要和技术路线图</strong> 🎨。</p><p><strong>图形摘要</strong>是把整篇论文压成一张图：问题是什么、怎么做的、得出什么结论，一眼看完。这玩意儿现在投稿基本是标配，编辑和审稿人第一眼看到的就是它。画的时候才发现，要把一篇文章塞进一张图里，比写论文还费脑子——每一句话都得变成图形语言，多余的东西一个都不能留。</p><p><strong>技术路线图</strong>则是把方法流程画清楚：数据从哪来、经过哪几步处理、每一步产出什么、最后落到什么结果。画完一看，整套研究的骨架清清楚楚，连我自己看着都觉得&quot;哦，原来我是这么干的&quot;。</p><p>两图画完，论文的完成度肉眼可见地又上了一档。</p><h2 id="新念头-北极渔业-🧊🐟" tabindex="-1">新念头：北极渔业 🧊🐟 <a class="header-anchor" href="#新念头-北极渔业-🧊🐟" aria-label="Permalink to &quot;新念头：北极渔业 🧊🐟&quot;">​</a></h2><p>然后是今天的重头戏——<strong>想开辟北极渔业的研究方向</strong>。</p><p>这个念头冒出来的时候我自己都兴奋了一下。北极那片海域，随着海冰消退、航运开通，渔业资源的格局正在剧烈变化；但相关的研究还远不如中低纬度海域那么充分。把这当成一个新方向去啃，既有科学意义，也有现实紧迫性。</p><p>跟自己做惯了的物种分布模型、三维生态位这套东西接得上——方法是可以迁移的，换的是研究对象和场景。这样一来不算从零开始，门槛没想象中那么高。</p><p><strong>准备最近研究一下</strong> 📚。先把文献摸一遍，看看别人做到哪了、还留着哪些空白，再判断自己能不能切进去、怎么切。新方向嘛，急不得，得先看清楚再动手。</p><p>科研最有意思的就是这种时刻——一个还没成形的想法，可能长成后面好几年的工作。</p><h2 id="就这样" tabindex="-1">就这样 <a class="header-anchor" href="#就这样" aria-label="Permalink to &quot;就这样&quot;">​</a></h2><p>今天汇报过了、图画好了、新方向也冒出来了。有收尾，也有开局，挺好的一天。</p><p>最近抽时间把北极渔业的文献啃一啃，看看这个坑值不值得跳。加油 💪！</p>',20)])])}const _=t(s,[["render",p]]);export{u as __pageData,_ as default};
